BATCH={'key':'mohawk_astk','label':'Montgomery County: Canajoharie, Fort Plain, Stone Arabia, Fonda, Auriesville','added':'2026-11-20 03:41'}
HM=lambda n,t: L('HMdb: '+t,'https://www.hmdb.org/m.asp?m=%d'%n)
